// Compile with the SDK include path and -DFH2_NAVIGATION_FILE=".../pause_navigation.inc".
// That private include is generated by tools/extract_horizon2_navigation.py.
// This harness supplies a tiny tab datasource; it executes the original FH2 routines.
#include <rex/ppc/context.h>
#include "../src/platform/fh2_navigation_adapter.h"
#include <array>
#include <cassert>
#include <cstdint>
#include <cstdio>
#include <stdexcept>
#include <initializer_list>

namespace {
constexpr uint32_t kMenu=0x1000,kControl=0x2000,kSource=0x3000,kItems=0x4000;
constexpr uint32_t kStack=0xE0000;
std::array<uint8_t,0x100000> memory{};
unsigned present=15,enabled=15;
bool has_source=true;
uint32_t Read(uint8_t* base,uint32_t address) {
  if(address>memory.size()-4 || address%4)throw std::out_of_range("guest read");
  return uint32_t(base[address])<<24 | uint32_t(base[address+1])<<16 |
         uint32_t(base[address+2])<<8 | base[address+3];
}
void Write(uint8_t* base,uint32_t address,uint32_t value) {
  if(address>memory.size()-4 || address%4)throw std::out_of_range("guest write");
  for(int i=3;i>=0;--i) {base[address+i]=uint8_t(value);value>>=8;}
}
void Dispatch(uint32_t target,PPCContext& ctx,uint8_t*) {
  switch(target) {
  case 1: // Tab control's datasource accessor.
    assert(ctx.r3.u32==kControl+0x6C);
    ctx.r3.u64=has_source?kSource:0;
    return;
  case 2: // Datasource item lookup.
    assert(ctx.r3.u32==kSource && ctx.r4.u32<4 && ctx.r5.u32==0);
    ctx.r3.u64=(present&(1u<<ctx.r4.u32))?kItems+ctx.r4.u32*32:0;
    return;
  case 3: // Item availability, used by the original code to skip locked tabs.
    assert(ctx.r3.u32>=kItems && ctx.r3.u32<kItems+4*32);
    ctx.r3.u64=(enabled>>(ctx.r3.u32-kItems)/32)&1;
    return;
  default:throw std::runtime_error("Unadapted FH2 virtual call");
  }
}
}

#define DEFINE_REX_FUNC(name) void name(PPCContext& ctx,uint8_t* base)
#define REX_FUNC_PROLOGUE() ((void)0)
#define REX_LOAD_U32(address) Read(base,uint32_t(address))
#define REX_STORE_U32(address,value) Write(base,uint32_t(address),uint32_t(value))
#define REX_CALL_INDIRECT_FUNC(target) Dispatch(uint32_t(target),ctx,base)
#ifndef FH2_NAVIGATION_FILE
#define FH2_NAVIGATION_FILE "pause_navigation.inc"
#endif
#include FH2_NAVIGATION_FILE

int main() {
  for(unsigned mask=0;mask<16;++mask)for(unsigned current=0;current<4;++current)
    for(int direction:{-1,1}) {
      auto expected=current;
      for(int i=int(current)+direction;i>=0 && i<4;i+=direction)
        if(mask&(1u<<i)) {expected=uint32_t(i);break;}
      assert(forza::fh2_navigation::Navigate(current,direction,mask)==expected);
    }
  auto base=memory.data();
  Write(base,kMenu+0x1B8,kControl);
  Write(base,kControl+0x6C,0x2800);Write(base,0x2804,1);
  Write(base,kSource,0x3800);Write(base,0x3808,2);
  for(unsigned i=0;i<4;++i) {
    Write(base,kItems+i*32,0x4800);
    Write(base,0x482C,3);
  }
  unsigned checks=0;
  for(present=0;present<16;++present)for(enabled=0;enabled<16;++enabled) {
    for(uint32_t current=0;current<4;++current)for(int direction:{-1,1}) {
      Write(base,kMenu+0x3A0,current);
      PPCContext ctx{};ctx.r1.u64=kStack;ctx.r3.u64=kMenu;ctx.lr=0x12345678;
      if(direction==1)fh2_pause_next_page(ctx,base);
      else fh2_pause_previous_page(ctx,base);
      auto expected=current;
      for(int i=int(current)+direction;i>=0 && i<4;i+=direction)
        if((present&enabled)&(1u<<i)) {expected=uint32_t(i);break;}
      assert(ctx.r3.u32==expected);
      assert(ctx.r1.u32==kStack && ctx.lr==0x12345678);
      assert(Read(base,kMenu+0x3A0)==current); // Navigation queries do not commit a page switch.
      ++checks;
    }
  }
  for(bool absent_control:{false,true}) {
    Write(base,kMenu+0x1B8,absent_control?0:kControl);has_source=false;
    Write(base,kMenu+0x3A0,2);
    PPCContext ctx{};ctx.r1.u64=kStack;ctx.r3.u64=kMenu;
    fh2_pause_next_page(ctx,base);assert(ctx.r3.u32==2);
    ctx.r3.u64=kMenu;fh2_pause_previous_page(ctx,base);assert(ctx.r3.u32==2);
    checks+=2;
  }
  std::printf("Original FH2 navigation: %u cases passed; runtime adapter: 128 cases passed\n",checks);
}
